"""Local extension to the existing RGB comparison, preserving previous page."""
import html,json,os,subprocess
from pathlib import Path
import numpy as np
from PIL import Image,ImageDraw
ROOT=Path(__file__).resolve().parents[1]
def read(p):return json.loads(p.read_text())
def main():
 diag=ROOT/'outputs/quality/diagnostics/RGB-132-r1';run=ROOT/'outputs/quality/diagnostics/RGB-133-r1';base=ROOT/'outputs/quality/backbone_comparison';r=read(run/'result.json');assert r['status']=='completed';d=read(diag/'result.json');c=read(ROOT/'experiments/runs/RGB-132-THREE-BACKBONE-DIAG/config.yaml');out=diag/'browser';out.mkdir(exist_ok=False)
 refs=base/'mip/export/images';frames=out/'frames';frames.mkdir()
 for i in range(144):
  n=f'frame{i:04d}.png';s=Image.new('RGB',(2640,1016),'white');dr=ImageDraw.Draw(s)
  for j,(label,path) in enumerate([('Mip RGB131 ORIGINAL',refs/n),('Mip RGB133 FILTER REFRESH',run/'images'/n)]):s.paste(Image.open(path),(1320*j,27));dr.text((1320*j+8,7),label,fill='black')
  s.save(frames/n)
 subprocess.run(['ffmpeg','-nostdin','-v','error','-n','-framerate','12','-i',str(frames/'frame%04d.png'),'-c:v','libx264','-threads','4','-crf','18','-pix_fmt','yuv420p','-movflags','+faststart',str(out/'mip-cache-before-after.mp4')],check=True)
 views=[]
 for n in c['views']:
  paths=[ROOT/'outputs/quality/all_data/RGB-120-r2/scene/images'/n,*[base/arm/'export/images'/n for arm in ['standard','scaffold','mip']],refs/n,run/'images'/n]
  views.append(dict(name=n,paths=[os.path.relpath(p,out) for p in paths],regions=[dict(name=k+(f' box{j+1}' if len(reg['boxes'])>1 else ''),box=box) for k,reg in c['regions'].items() if reg['view']==n for j,box in enumerate(reg['boxes'])]))
 old=read(base/'mip/rgb-evaluation/result.json')['metrics'];delta={k:r['metrics'][k]-old[k] for k in old};stats=dict(old=old,new=r['metrics'],delta=delta,changed_views=sum(x['changed_pixels']>0 for x in r['rows'][:400]),regions=r['regions'],rows=d['rows'])
 (out/'data.json').write_text(json.dumps(dict(views=views,stats=stats),ensure_ascii=False,indent=2)+'\n')
 review=html.escape((diag/'review.md').read_text()) if (diag/'review.md').exists() else '结果复核进行中。'
 page='''<!doctype html><meta charset="utf-8"><title>三骨干问题诊断与Mip单变量验证</title><style>body{font:15px/1.6 system-ui;margin:28px;background:#f6f7f9;color:#17202a}h1{font-size:25px}h2{font-size:19px}p{max-width:1100px}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}.pair{display:grid;grid-template-columns:1fr 1fr;gap:12px}.tile{background:white}.tile p{margin:5px}canvas,video{width:100%;display:block}button,select{padding:8px;margin:5px}table{border-collapse:collapse;background:white}td,th{padding:8px;border-bottom:1px solid #ddd;text-align:right}.review{white-space:pre-wrap;max-width:1150px}a{color:#075daf}</style><h1>三骨干同位置诊断 · 一次Mip缓存刷新验证</h1><p>父：Standard RGB130、Scaffold RGB120、Mip RGB131；RGB132只读诊断，RGB133只改Mip滤波缓存，无训练。旧模型和旧对照页面保持。数据角色：全400 RGB训练内；标签仅作区域评价；144新相机无GT。</p><div class=review>__REVIEW__</div><h2>Mip自身基线与候选的全400指标</h2>__TABLE__<p>缓存更新幅度不等于质量改善；不把单算法结果外推。Scaffold主图为SEM370固定UID0，其训练UID补充结果见原对照页。</p><select id=view></select><select id=region></select><button id=full>完整原生画面</button><span id=box></span><h2>相同位置：照片 / Standard / Scaffold / Mip</h2><div class=grid id=three></div><h2>唯一修复：Mip原始 / Mip缓存刷新</h2><div class=pair id=pair></div><h2>同144相机轨迹，左原始、右刷新</h2><p>RGB未缩放，每幅1320×989；视频仅增加27像素标题栏，12fps。无GT，只作视觉复核。</p><video controls src=mip-cache-before-after.mp4></video><p><a href=data.json>完整同区域统计</a> · <a href=../../../backbone_comparison/browser-r1/index.html>原三系统完整对照</a></p><script>const V=__V__;let k=0,box=[0,0,1320,989],items=[],version=0;const v=document.querySelector('#view'),r=document.querySelector('#region');V.forEach((x,i)=>v.add(new Option(x.name,i)));function draw(){document.querySelector('#box').textContent=JSON.stringify(box);for(const {im,c} of items){c.width=box[2]-box[0];c.height=box[3]-box[1];c.getContext('2d').drawImage(im,box[0],box[1],c.width,c.height,0,0,c.width,c.height)}}function load(){version++;const token=version;items=[];r.replaceChildren();r.add(new Option('选择固定区域',''));V[k].regions.forEach((x,i)=>r.add(new Option(x.name,i)));document.querySelector('#three').replaceChildren();document.querySelector('#pair').replaceChildren();V[k].paths.forEach((path,i)=>{const tile=document.createElement('div');tile.className='tile';const p=document.createElement('p');p.textContent=['照片','Standard RGB130','Scaffold RGB120 UID0','Mip RGB131','Mip RGB131 原始','Mip RGB133 仅刷新缓存'][i];const c=document.createElement('canvas'),a=document.createElement('a');a.href=path;a.textContent='原生图';a.target='_blank';tile.append(p,c,a);document.querySelector(i<4?'#three':'#pair').append(tile);const im=new Image();im.onload=()=>{if(token===version){items.push({im,c});draw()}};im.src=path})}v.onchange=()=>{k=+v.value;box=[0,0,1320,989];load()};r.onchange=()=>{if(r.value!==''){box=V[k].regions[+r.value].box;draw()}};document.querySelector('#full').onclick=()=>{box=[0,0,1320,989];draw()};load();</script>'''
 table='<table><tr><th>指标</th><th>RGB131原始</th><th>RGB133刷新</th><th>候选−原始</th></tr>'+''.join(f'<tr><td>{k}</td><td>{old[k]:.9f}</td><td>{r["metrics"][k]:.9f}</td><td>{delta[k]:+.9f}</td></tr>' for k in old)+'</table>'
 (out/'index.html').write_text(page.replace('__REVIEW__',review).replace('__TABLE__',table).replace('__V__',json.dumps(views)));print(out/'index.html')
if __name__=='__main__':main()
